test('signed bounded member traversal with unknown joining dates; stale policy/filter/actor rejection',async()=>{const o=await setup();await database.transaction(async tx=>{for(let n=0;n<22;n++){const u=await tx.user.create({data:{name:'Page '+String(n).padStart(2,'0')}}),m=await tx.workspaceMembership.create({data:{workspaceId:o.ws,userId:u.id,role:'MEMBER',status:n===0?'SUSPENDED':'ACTIVE'}});await tx.teamMembership.create({data:{workspaceId:o.ws,teamId:o.team,membershipId:m.id,joinedAt:n<2?null:new Date('2026-01-01')}});}});let r=await o.f.http(endpoint(o,'memberships')+'?limit=20','GET',o.client);expect(r.status).toBe(200);const first=await r.json();expect(first.items).toHaveLength(20);expect(first.items[0].joinedAt).toBeNull();expect(first.items[1].joinedAt).toBeNull();r=await o.f.http(endpoint(o,'memberships')+'?limit=20&after='+first.page.nextCursor,'GET',o.client);expect(r.status).toBe(200);const second=await r.json();expect(second.items).toHaveLength(3);expect(new Set([...first.items,...second.items].map((m:{membershipId:string})=>m.membershipId)).size).toBe(23);expect((await o.f.http(endpoint(o,'memberships')+'?limit=19&after='+first.page.nextCursor,'GET',o.client)).status).toBe(400);const encoded=first.page.nextCursor.split('.')[0],payload=JSON.parse(Buffer.from(encoded,'base64url').toString()),old=Buffer.from(JSON.stringify({...payload,issued:Date.now()-1000000,expires:Date.now()-1000})).toString('base64url'),signed=createHmac('sha256',Buffer.from(workspaceKeys.cursors.v1,'hex')).update('unblok-team-members-cursor-v1\0'+old).digest('base64url');expect((await o.f.http(endpoint(o,'memberships')+'?limit=20&after='+old+'.'+signed,'GET',o.client)).status).toBe(400);const m=await database.client.workspaceMembership.findFirstOrThrow({where:{workspaceId:o.ws,role:'MEMBER',status:'ACTIVE'}});await database.client.workspaceMembership.update({where:{workspaceId_id:{workspaceId:o.ws,id:m.id}},data:{status:'SUSPENDED'}});expect((await o.f.http(endpoint(o,'memberships')+'?limit=20&after='+first.page.nextCursor,'GET',o.client)).status).toBe(409);expect((await o.f.http(endpoint(o,'memberships')+'?status=SUSPENDED','GET',o.client)).status).toBe(200);});

