 await writeFile(resolve(root,'docs/backend/evidence/be-team-02/F1-success-performance.json'),JSON.stringify({workload:'Fresh legitimate account/Workspace per burst; directory50 requests at1/10/50 concurrency (<60 read/min/account); management20 inert role requests at1/10 concurrency (=20 management/min/account). No admission resets, timeout changes or automatic retries. Each directory burst has1001 explicit joins and120-character member names. Management inert role workload has2 explicit joins. Percentiles describe finite local bursts, not steady-state capacity.',loads,directorySql,limitations:'Admission timing is Team Valkey consume only, excludes coarse/session/primary authorization. SQL EXPLAIN execution excludes HTTP/admission. pg_stat_activity/pg_locks.waitstart sampling measures longest observed pending PostgreSQL lock duration independently, not total cumulative lock-wait duration; waits shorter than10ms may be missed.'},null,2)+'\n');
