test('Workspace2000/deployment20000 caps preserve authorized management replay and immutable tombstone status',async()=>{const o=await setup(),t=await target(o,'MEMBER'),v=await ver(o),key=randomUUID(),body={membershipId:t.member,teamRole:'MEMBER'};expect((await manage(o,'memberships',body,o.client,key,v)).status).toBe(201);const seed=async(ws:string,team:string,count:number)=>{for(let remaining=count;remaining>0;remaining-=Math.min(500,remaining)){const batch=Math.min(500,remaining);await database.transaction(async tx=>{await tx.$queryRaw`SELECT id FROM workspaces WHERE id=${ws}::uuid FOR UPDATE`;await tx.$executeRaw`INSERT INTO team_mutation_results(id,workspace_id,actor_id,operation,request_key,payload_digest,team_id,result,completed_at,retain_until) SELECT gen_random_uuid(),${ws}::uuid,${o.userId}::uuid,'team:create:v1',gen_random_uuid(),repeat('a',64),${team}::uuid,NULL,statement_timestamp()-interval '25 hours',statement_timestamp()-interval '1 hour' FROM generate_series(1,${batch})`;});}};await seed(o.ws,o.team,2000-await budget('workspace:'+o.ws));const before=await ver(o);expect((await manage(o,'memberships/'+t.member,{teamRole:'OBSERVER'},o.client,randomUUID(),undefined,'PATCH')).status).toBe(503);expect(await ver(o)).toBe(before);expect((await manage(o,'memberships',body,o.client,key,v)).status).toBe(201);const receipt=await database.client.teamMutationResult.findFirstOrThrow({where:{workspaceId:o.ws,operation:'team:add:v1'}});await expect(Promise.resolve(database.client.teamMutationResult.update({where:{id:receipt.id},data:{httpStatus:200}}))).rejects.toThrow();while(await budget('deployment')<20000){const ws=randomUUID(),member=randomUUID(),team=randomUUID();await database.transaction(async tx=>{await tx.workspace.create({data:{id:ws,name:'Capacity',slug:ws}});await tx.workspaceMembership.create({data:{workspaceId:ws,id:member,userId:o.userId,role:'ADMIN',status:'ACTIVE'}});await tx.team.create({data:{workspaceId:ws,id:team,key:'CAP',name:'Capacity',ownerMembershipId:member}});await tx.teamMembership.create({data:{workspaceId:ws,teamId:team,membershipId:member}});});await seed(ws,team,Math.min(2000,20000-await budget('deployment')));}expect(await budget('deployment')).toBe(20000);expect((await manage(o,'memberships',body,o.client,key,v)).status).toBe(201);await expect(Promise.resolve(database.client.$executeRaw`UPDATE team_receipt_budgets SET used=0 WHERE scope='deployment'`)).rejects.toThrow();expect(await database.client.teamMembership.count({where:{workspaceId:o.ws,teamId:o.team}})).toBe(2);},60000);
